const ASSETS={"/app.js":{"body":"const animals={\r\n'고양이':['🐱',[\r\n['고양이 수염은 어떤 일을 하나요?','수염은 주변 물체와 공기의 움직임을 느끼는 데 도움을 줘요. 좁은 곳을 살필 때도 도움이 돼요.'],\r\n['고양이는 왜 가르릉 소리를 내나요?','편안할 때 가르릉 소리를 내기도 해요. 하지만 아프거나 불안할 때도 낼 수 있어, 소리만으로 기분을 정하기는 어려워요.'],\r\n['고양이는 왜 발톱을 긁나요?','발톱의 바깥층을 관리하고 몸을 쭉 펴는 행동이에요. 자신의 흔적을 남기는 역할도 해요.'],\r\n['고양이는 어두운 곳에서도 볼 수 있나요?','사람보다 적은 빛에서도 잘 볼 수 있어요. 하지만 빛이 전혀 없으면 볼 수 없어요.'],\r\n['고양이는 모두 물을 싫어하나요?','모든 고양이가 물을 싫어하는 것은 아니에요. 고양이마다 경험과 성향이 달라요.']]],\r\n'강아지':['🐶',[\r\n['강아지는 왜 산책을 하나요?','몸을 움직이고 주변의 다양한 냄새와 환경을 경험할 수 있어요. 산책 방법과 시간은 건강과 나이에 맞춰야 해요.'],\r\n['강아지는 왜 냄새를 맡나요?','냄새로 주변에 대한 정보를 얻어요. 사람이나 다른 동물의 흔적을 알아보는 데도 도움이 돼요.'],\r\n['강아지가 꼬리를 흔들면 항상 기쁜가요?','항상 기쁘다는 뜻은 아니에요. 긴장하거나 경계할 때도 흔들 수 있어 몸 전체의 모습을 함께 봐야 해요.'],\r\n['강아지는 왜 혀를 내밀고 헐떡이나요?','몸의 열을 내보내는 데 도움이 돼요. 더위뿐 아니라 운동이나 긴장 등 여러 이유가 있어요.'],\r\n['강아지는 사람보다 소리를 잘 듣나요?','사람이 듣기 어려운 높은 소리를 들을 수 있어요. 다만 듣는 능력은 나이와 건강에 따라 달라요.']]],\r\n'토끼':['🐰',[\r\n['토끼의 귀는 왜 길까요?','소리를 듣고 몸의 열을 조절하는 데 도움이 돼요. 귀의 길이는 토끼 종류마다 달라요.'],\r\n['토끼는 당근만 먹나요?','당근만 먹지 않아요. 반려 토끼에게는 건초가 중요한 먹이예요.'],\r\n['토끼의 이는 계속 자라나요?','토끼의 이는 계속 자라요. 먹이를 씹으며 적절히 닳는 것이 중요해요.'],\r\n['토끼는 어떻게 움직이나요?','힘이 센 뒷다리를 사용해 뛰어요. 천천히 이동할 때와 달릴 때의 모습은 달라요.'],\r\n['토끼는 모두 눈이 빨간가요?','모두 빨갛지는 않아요. 갈색 등 다양한 눈 색깔이 있어요.']]],\r\n'햄스터':['🐹',[\r\n['햄스터 볼은 왜 볼록해지나요?','볼 안의 주머니에 먹이를 담아 옮길 수 있어요. 먹이를 보관할 곳으로 가져가기도 해요.'],\r\n['햄스터는 언제 활동하나요?','대체로 저녁이나 밤에 활동하는 경우가 많아요. 종류와 환경에 따라 차이가 있어요.'],\r\n['햄스터는 왜 쳇바퀴를 타나요?','움직이고 달리는 활동을 할 수 있기 때문이에요. 몸에 맞는 안전한 크기가 중요해요.'],\r\n['햄스터는 모두 함께 키워도 되나요?','종류에 따라 다르며 함께 살면 싸울 수 있어요. 특히 골든햄스터는 따로 키워야 해요.'],\r\n['햄스터도 이를 관리해야 하나요?','앞니가 계속 자라기 때문에 적절히 닳아야 해요. 먹기 어려워 보이면 보호자가 수의사에게 확인해야 해요.']]],\r\n'펭귄':['🐧',[\r\n['펭귄은 모두 남극에 사나요?','모두 남극에 살지는 않아요. 남아프리카나 갈라파고스 등 다른 지역에 사는 펭귄도 있어요.'],\r\n['펭귄은 새인가요?','펭귄은 새예요. 깃털이 있고 알을 낳아요.'],\r\n['펭귄은 하늘을 날 수 있나요?','하늘을 날지는 못해요. 대신 날개를 이용해 물속에서 헤엄쳐요.'],\r\n['펭귄은 무엇을 먹나요?','종류와 사는 곳에 따라 물고기, 크릴, 오징어 등을 먹어요.'],\r\n['펭귄은 왜 무리 지어 있나요?','번식하거나 몸의 열을 지키는 등 여러 이유가 있어요. 모든 펭귄의 생활 방식이 같은 것은 아니에요.']]]};\r\nconst topics={\r\nanimals:{name:'동물',title:'동물 친구들',icon:'🐾'},\r\nmeals:{name:'급식',title:'오늘 뭐 먹어요?',icon:'🍚',q:['오늘 급식 메뉴는 무엇인가요?','내일 급식에는 무엇이 나오나요?','이번 주에 어떤 과일이 나오나요?','이번 주에 제가 좋아하는 음식이 나오나요?','급식 메뉴 이름이 어려워요. 어떤 음식인가요?'],reply:'학교 급식표는 아직 이 시연 앱에 연결되지 않았어요. 선생님과 해당 날짜의 급식표에서 메뉴를 확인해 봐요.'},\r\nevents:{name:'학교 행사',title:'학교에서 무슨 일이 있나요?',icon:'🏫',q:['가장 가까운 학교 행사는 무엇인가요?','우리 학교 운동회는 언제인가요?','학교 행사는 어디에서 하나요?','현장체험학습에 무엇을 준비해야 하나요?','비가 오면 행사 일정이 바뀌나요?'],reply:'학교 행사 자료는 아직 연결되지 않았어요. 계획된 일정은 바뀔 수 있으니 선생님과 최근 학교 안내를 확인해 봐요.'},\r\nweather:{name:'날씨',title:'하늘이 궁금해요',icon:'☀️',q:['오늘 우리 동네 날씨는 어떤가요?','내일 비가 올까요?','오늘은 어제보다 추운가요?','이번 주에 비가 예보된 날은 언제인가요?','학교 행사 날의 날씨 예보가 나왔나요?'],reply:'이 시연 앱은 실시간 날씨를 가져오지 않아요. 직접 찾아보기에서 기상청 예보를 찾아 지역, 날짜, 발표 시각을 함께 확인해 봐요.'},\r\nrecycle:{name:'분리배출',title:'어디에 버릴까요?',icon:'♻️',q:['우유팩은 어떻게 분리배출하나요?','페트병은 어떻게 분리배출하나요?','음식물이 묻은 종이는 어디에 버리나요?','다 쓴 건전지는 어디에 버리나요?','과자 봉지는 어디에 버리나요?'],reply:'물건의 재질과 상태, 지역 수거 기준에 따라 방법이 달라질 수 있어요. 우리 지역의 공식 분리배출 안내를 찾아봐요. 지역마다 수거 방법이 다를 수 있으니 안내의 지역과 날짜도 살펴봐요.'},\r\nbooks:{name:'도서',title:'책 속으로 떠나요',icon:'📚',q:['학교 도서관에 고양이 책이 있나요?','이 책을 쓴 사람은 누구인가요?','이 책은 어떤 내용인가요?','책을 몇 권 빌릴 수 있나요?','빌린 책은 언제까지 돌려줘야 하나요?'],reply:'도서 목록은 아직 연결되지 않았어요. 책 정보는 표지나 도서 목록에서 확인하고, 대출 규칙과 현재 대출 가능 여부는 도서관 담당 선생님께 물어봐요.'},\r\ndaily:{name:'일상생활',title:'매일의 작은 궁금증',icon:'🌱',q:['준비물을 잊지 않으려면 어떻게 할까요?','젖은 신발은 어떻게 말리나요?','친구에게 고마움을 어떻게 표현할까요?','아침에 일어나는 것을 어떻게 준비할까요?','사용한 물건을 어떻게 정리하면 좋을까요?'],answers:['준비물 목록을 만들고 가방에 넣을 때 하나씩 표시해 보세요. 자기 전에 한 번 더 확인해도 좋아요.','신발의 관리 표시를 먼저 확인해요. 가능한 신발은 깔창을 빼고 통풍이 되는 곳에서 말려요. 뜨거운 열은 신발을 손상시킬 수 있어요.','어떤 점이 고마웠는지 구체적으로 말해 보세요. 짧은 편지로 마음을 전할 수도 있어요.','전날 필요한 물건을 준비하고, 보호자와 일정한 잠자리 시간을 정해 볼 수 있어요. 자신에게 맞는 방법을 찾아봐요.','물건마다 놓을 자리를 정하고, 사용한 뒤 그 자리에 돌려놓아 보세요. 글이나 그림 표시도 도움이 돼요.']}\r\n};\r\nlet active='animals',animal='고양이';const records=[];let latest=-1;const $=id=>document.getElementById(id);const initial=$('messages').innerHTML;\r\nfunction render(){ $('categories').replaceChildren();Object.entries(topics).forEach(([key,t])=>{const b=document.createElement('button');b.className='category'+(active===key?' active':'');b.setAttribute('aria-pressed',String(active===key));const i=document.createElement('i');i.textContent=t.icon;const n=document.createElement('span');n.textContent=t.name;const arrow=document.createElement('span');arrow.textContent='↗';b.append(i,n,arrow);b.onclick=()=>{active=key;render()};$('categories').append(b)});const t=topics[active];$('topic-title').textContent=t.title;$('topic-icon').textContent=t.icon;$('animals').replaceChildren();if(active==='animals')Object.entries(animals).forEach(([name,[icon]])=>{const b=document.createElement('button');b.className='animal'+(animal===name?' active':'');b.textContent=icon+' '+name;b.setAttribute('aria-pressed',String(animal===name));b.onclick=()=>{animal=name;render()};$('animals').append(b)});$('questions').replaceChildren();const qs=active==='animals'?animals[animal][1].map(p=>p[0]):t.q;qs.forEach(q=>{const b=document.createElement('button');b.className='question-card';const mark=document.createElement('span');mark.textContent='↗';b.append(mark,document.createTextNode(q));b.onclick=()=>{$('question').value=q;$('question').focus()};$('questions').append(b)});if(typeof renderEasy==='function')renderEasy()}\r\nfunction addMessage(text,who){const box=document.createElement('div');box.className='message '+who;const label=document.createElement('strong');label.textContent=who==='user'?'나의 질문':'시연용 안내 · 실제 AI 답변 아님';box.append(label,document.createTextNode(text));$('messages').append(box);$('messages').scrollTop=$('messages').scrollHeight}\r\nfunction answer(q){for(const [,pairs] of Object.values(animals)){const p=pairs.find(p=>p[0]===q);if(p)return p[1]+'\\n\\n미리 준비한 설명이에요. 도감이나 관련 기관 자료에서도 확인해 봐요.'}for(const t of Object.values(topics)){const idx=t.q?.indexOf(q);if(idx>=0)return t.answers?t.answers[idx]+'\\n\\n미리 준비한 생활 속 제안이에요. 상황에 맞는 방법을 선생님과 이야기해 봐요.':t.reply}return '질문을 잘 적어 주었어요! 지금은 API 없는 시연 모드여서 이 질문을 이해하고 새로운 답을 만들 수는 없어요.\\n준비된 예시 질문으로 연습하거나, 「직접 찾아보기」를 눌러 선생님과 검색해 봐요.'}\r\n$('chat-form').onsubmit=e=>{e.preventDefault();const q=$('question').value.trim();if(!q){$('question').focus();return}const response=answer(q);records.push({question:q,answer:response,judgment:'',reason:'',topic:topics[active].name});latest=records.length-1;addMessage(q,'user');addMessage(response,'bot');$('question').value='';document.querySelectorAll('[name=judgment]').forEach(x=>x.checked=false);$('reason').value='';$('judgment-status').textContent=''};\r\n$('save-judgment').onclick=()=>{const j=document.querySelector('[name=judgment]:checked');$('judgment-status').textContent=j?'내 판단: '+j.value+($('reason').value.trim()?' · '+$('reason').value.trim():' · 근거는 선생님께 말해 보세요.'):'먼저 판단을 하나 골라 주세요.'};\r\n$('reset').onclick=()=>{if(!confirm('대화와 판단을 지우고 새로 시작할까요?'))return;$('messages').innerHTML=initial;$('question').value='';$('reason').value='';$('judgment-status').textContent='';document.querySelectorAll('[name=judgment]').forEach(x=>x.checked=false);records.length=0;latest=-1;if($('result'))$('result').hidden=true;active='animals';animal='고양이';render()};render();\r\n","type":"text/javascript;charset=utf-8"},"/connection.js":{"body":"const simpleTopics={\nanimals:easyPairs,\nmeals:[{icon:'🍚 📅 ❓',q:'오늘 뭐 먹어요?'},{icon:'🍎 🍌 ❓',q:'과일이 나와요?'}],\nevents:[{icon:'🏫 🎉 ❓',q:'학교에 무슨 행사가 있어요?'},{icon:'🎒 🚌 ❓',q:'소풍은 언제 가요?'}],\nweather:[{icon:'☀️ ☁️ ❓',q:'오늘 날씨 어때요?'},{icon:'🌧️ ☂️ ❓',q:'내일 비 와요?'}],\nrecycle:[{icon:'🥛 ♻️ ❓',q:'우유팩은 어디에 버려요?'},{icon:'🔋 ♻️ ❓',q:'건전지는 어디에 버려요?'}],\nbooks:[{icon:'🐱 📚 ❓',q:'고양이 책 있어요?'},{icon:'📖 ✍️ ❓',q:'이 책은 누가 썼어요?'}],\ndaily:[{icon:'🎒 ✅ ❓',q:'가방에 다 넣었나요?'},{icon:'🧸 🧺 ❓',q:'장난감은 어디에 놓아요?'}]\n};\nconst previousAnswer=answer;answer=q=>{for(const [key,pairs] of Object.entries(simpleTopics)){if(key==='animals')continue;const idx=pairs.findIndex(p=>p.q===q);if(idx>=0){if(key==='daily')return idx===0?'준비물 목록을 보고 가방에 넣은 것을 하나씩 표시해 봐요.':'장난감 자리를 정하고 놀이가 끝나면 그곳에 놓아요.';return topics[key].reply}}return previousAnswer(q)};\nrenderEasy=function(){const root=$('easy-questions');root.replaceChildren();(simpleTopics[active]||easyPairs).forEach(p=>{const wrap=document.createElement('div');wrap.className='easy-item';const b=document.createElement('button');b.className='easy-card';const icon=document.createElement('span');icon.className='easy-icon';icon.textContent=p.icon;const text=document.createElement('b');text.textContent=p.q;b.append(icon,text);b.onclick=()=>{$('question').value=p.q};const read=document.createElement('button');read.className='read';read.textContent='🔊';read.setAttribute('aria-label',p.q+' 소리로 듣기');read.onclick=()=>{if(!window.speechSynthesis){alert('이 기기에서는 읽어주기를 지원하지 않아요.');return}speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(p.q);utterance.lang='ko-KR';utterance.rate=.8;speechSynthesis.speak(utterance)};wrap.append(b,read);root.append(wrap)})};renderEasy();\nconst settings=dialog('⚙️ 교사용 API 연결');settings.innerHTML='<div class=\"dialog-heading\"><h2>⚙️ 교사용 API 연결</h2><button class=\"quiet\" id=\"close-settings\">닫기 ✕</button></div><p>다른 업체의 <b>OpenAI 호환 Chat Completions API</b>를 연결할 수 있어요. 모든 API가 이 방식과 호환되는 것은 아니에요.</p><p>입력한 키는 서버에서 암호화되어 이 브라우저의 보안 세션에만 연결됩니다. 8시간 후 또는 연결 해제 시 다시 입력해야 해요. 학생 개인정보는 입력하지 마세요.</p><form id=\"api-form\" autocomplete=\"off\"><label for=\"api-url\">연결 주소 (전체 HTTPS URL)</label><input id=\"api-url\" type=\"url\" required placeholder=\"https://업체주소/v1/chat/completions\"><label for=\"api-model\">모델 이름</label><input id=\"api-model\" required maxlength=\"120\" placeholder=\"업체에서 안내하는 모델 이름\"><label for=\"api-key\">API 키</label><input id=\"api-key\" type=\"password\" required autocomplete=\"new-password\" maxlength=\"1000\" placeholder=\"키는 저장 후 다시 표시하지 않아요\"><p>저장하면 이후 질문과 최근 대화가 위 업체로 전송되고, 업체 정책에 따라 요금이 발생할 수 있어요. 초등학생 대상 이용이 허용되는 서비스인지 확인해 주세요.</p><button class=\"send\" type=\"submit\">이 설정으로 연결하기</button></form><button id=\"disconnect\" class=\"quiet\">연결 해제 · 시연 모드로 돌아가기</button><p id=\"api-status\" role=\"status\"></p>';\nconst settingsButton=document.createElement('button');settingsButton.className='quiet';settingsButton.textContent='⚙️ API 설정';document.querySelector('header').append(settingsButton);settingsButton.onclick=()=>settings.showModal();$('close-settings').onclick=()=>settings.close();let live=false,busy=false;\nasync function api(path,options={}){const r=await fetch(path,{...options,headers:{'Content-Type':'application/json',...options.headers}});let body;try{body=await r.json()}catch{throw Error('현재 서버에서는 API 연결을 지원하지 않아요. 배포된 사이트에서 열어 주세요.')}if(!r.ok)throw Error(body.error||'요청을 완료하지 못했어요.');return body}\nfunction mode(){document.querySelector('.demo').textContent=live?'● 외부 API 연결 모드':'● API 없는 시연 모드';document.querySelector('.chat-heading span').textContent=live?'외부 AI 답변 · 중요한 내용은 확인해요':'질문 → 찾아보기 → 내 판단'}\n$('api-form').onsubmit=async e=>{e.preventDefault();$('api-status').textContent='연결 설정을 저장하고 있어요…';try{const body=await api('/api/config',{method:'POST',body:JSON.stringify({url:$('api-url').value.trim(),model:$('api-model').value.trim(),key:$('api-key').value.trim()})});live=true;$('api-key').value='';mode();$('api-status').textContent='설정을 저장했어요. 실제 응답은 질문을 보내면 확인할 수 있어요.'}catch(e){$('api-status').textContent=e.message}};\n$('disconnect').onclick=async()=>{try{await api('/api/config',{method:'DELETE'});live=false;mode();$('api-key').value='';$('api-status').textContent='연결을 해제했어요.'}catch(e){$('api-status').textContent=e.message}};\napi('/api/config').then(c=>{live=c.connected;if(live){$('api-url').value=c.url;$('api-model').value=c.model;$('api-status').textContent='이 브라우저의 연결 설정이 있어요.'}mode()}).catch(()=>{});\nconst demoSubmit=$('chat-form').onsubmit;\n$('chat-form').onsubmit=async e=>{if(!live)return demoSubmit(e);e.preventDefault();if(busy)return;const q=$('question').value.trim();if(!q)return;busy=true;const send=$('chat-form').querySelector('.send');send.disabled=true;send.textContent='답변 중…';addMessage(q,'user');$('question').value='';try{const history=records.filter(r=>r.live).slice(-6).flatMap(r=>[{role:'user',content:r.question},{role:'assistant',content:r.answer}]);const result=await api('/api/chat',{method:'POST',body:JSON.stringify({messages:[...history,{role:'user',content:q}]})});records.push({question:q,answer:result.answer,judgment:'',reason:'',topic:topics[active].name,live:true});latest=records.length-1;addMessage(result.answer,'bot');$('messages').lastElementChild.querySelector('strong').textContent='외부 AI 답변 · 다른 자료에서 확인해요';document.querySelectorAll('[name=judgment]').forEach(x=>x.checked=false);$('reason').value='';$('judgment-status').textContent=''}catch(err){addMessage(err.message+'\\n설정을 확인하거나 시연 모드로 돌아가 주세요.','bot');$('messages').lastElementChild.querySelector('strong').textContent='연결 오류 · AI 답변 아님';$('question').value=q}finally{busy=false;send.disabled=false;send.textContent='질문 보내기 ↗'}};\nreportRows=function(){return records.map((r,i)=>({title:`${i+1}. ${r.question}`,body:[`${r.live?'외부 AI 답변':'시연 답변'}: ${r.answer.replace(/\\n\\n[\\s\\S]*/,'')}`,`내 판단: ${r.judgment||'아직 남기지 않았어요.'}`,`확인 자료와 근거: ${r.reason||'기록하지 않았어요.'}`]}))};\n","type":"text/javascript;charset=utf-8"},"/cute.css":{"body":"body{background:#fffaf3;background-image:radial-gradient(#eadfd2 1px,transparent 1px);background-size:24px 24px;color:#494157}header{border-color:#e7dce9}.brand,h1,h2,.category,.animal,.easy-card{font-family:'Jua','Noto Sans KR',sans-serif;font-weight:400}.logo{background:#8b71b3;border-radius:16px 16px 16px 5px}.intro{padding-top:14px}h1{font-size:49px;letter-spacing:-1px}h1 em{color:#8a64a9}.eyebrow{color:#927b9e}.intro p{color:#786e7d}.book{background:#fce3b0;border:2px solid #b28b67;box-shadow:8px 7px 0 #e8d8f4;border-radius:28px 36px 36px 14px;color:#705252;transform:rotate(8deg)}.book b{color:#75584f}.bubble{border-color:#e4d3ed;color:#9270a2;background:#fff8ff}.spark{color:#db9a62}.panel{border:2px solid #eadff0;border-radius:32px;box-shadow:0 7px 0 #eee2f0}.category{font-size:19px;border-radius:18px}.category.active{background:#9476b5;box-shadow:0 4px 0 #755c93}.category:hover:not(.active){background:#f1e6f6}.category:nth-child(2) i{background:#ffedcf}.category i{display:grid;place-items:center;width:40px;height:40px;border-radius:14px;background:#fff5}.tip{border-color:#e9deeb}.panel-head h2{color:#6e5289;font-size:28px}.animal{border-color:#e5d8ee;padding:12px 15px;font-size:17px}.animal.active{background:#f4e7fc;color:#79529c;border-color:#b390cd}.question-card{background:#fffaf2;border-color:#f0e6d8;border-radius:16px;color:#665770;min-height:66px}.question-card:hover{background:#f8edfc;border-color:#c8a6da}.question-card span{color:#b798c6}.easy{padding:18px;border-radius:22px;background:#fff0e5;border:1px solid #f4dac8;margin-bottom:20px}.easy h3{font-size:15px;margin:0 0 12px;color:#98704e}.easy small{display:block;font-size:11px;line-height:1.7;color:#8b735f;margin-top:10px}#easy-questions{display:grid;grid-template-columns:1fr 1fr;gap:12px}.easy-item{position:relative}.easy-card{width:100%;padding:12px 36px 15px 12px;border:2px solid #edcfb7;border-radius:18px;background:white;color:#6b5365;cursor:pointer;min-height:112px}.easy-icon{display:block;font-size:34px;letter-spacing:4px;margin-bottom:8px}.easy-card b{font-size:18px;font-weight:400}.read{position:absolute;right:8px;top:8px;border:0;background:#fff1d5;border-radius:50%;width:32px;height:32px;cursor:pointer}.send{background:#9476b5;border-radius:16px;box-shadow:0 3px 0 #755c93}.send:disabled{opacity:.6;cursor:wait}.input-row textarea{border:2px solid #e5d7ed;border-radius:18px}.welcome,.message.bot{background:#f6f0fa;color:#685574}.message.user{background:#fff0cf}.chat-heading{border-color:#eadff0}.search{background:#eaf5ed;color:#537d60;border-color:#d0e6d6;border-radius:16px}.quiet{border-color:#e0d4e8;color:#775d8b;border-radius:13px}details{border-color:#eadff0}summary{color:#82659a}fieldset label{background:#f7effb;padding:12px;border-radius:12px}#reason{border-color:#e5d7ed}input[type=radio]{accent-color:#9476b5}.result{margin-top:22px;padding:24px;background:#fff9e9;border:2px dashed #e7cca1;border-radius:22px}.result[hidden]{display:none}.result h2{margin:10px 0;color:#8c6952;font-size:25px}.result>p{font-size:12px;color:#857664;line-height:1.8}.result article{background:white;border-radius:14px;padding:15px;margin:12px 0;border:1px solid #f0e4d3}.result article h3{font-size:15px;line-height:1.6;color:#785a89}.result article p{font-size:13px;white-space:pre-wrap;line-height:1.8;overflow-wrap:anywhere}.result .send{width:100%;padding:16px;font-size:16px;margin-top:10px}footer{background:#fff9f2f5;border-color:#e9dfd2;color:#84738c}@media(max-width:800px){h1{font-size:36px}.category{font-size:16px;padding:10px}.category i{width:30px;height:30px}.panel{padding:18px}.easy{padding:12px}.easy-card{padding:12px 8px}.easy-icon{font-size:27px;letter-spacing:1px}.easy-card b{font-size:16px}.read{top:3px;right:3px;width:26px;height:26px}.result{padding:15px}}\n/* Keep long question lists and tabs inside narrow screens. */\n.workspace{grid-template-columns:265px minmax(0,1fr)}.workspace>*,.panel,.input-row,textarea{min-width:0}.categories{max-width:100%}header{flex-wrap:wrap;height:auto;min-height:88px;padding-top:15px;padding-bottom:15px}.intro{min-width:0}@media(max-width:800px){.workspace{grid-template-columns:minmax(0,1fr)}header{gap:8px;min-height:75px}.brand{font-size:17px}.demo{font-size:9px}header .quiet{font-size:10px;padding:7px}.categories .category{flex-shrink:0}.input-row{width:100%}.easy-card{overflow-wrap:anywhere}.chat-heading{flex-wrap:wrap}}\n","type":"text/css;charset=utf-8"},"/index.html":{"body":"<!doctype html>\r\n<html lang=\"ko\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>궁금한 교실 · 질문하고 확인해요</title><link rel=\"stylesheet\" href=\"style.css\"><link rel=\"stylesheet\" href=\"cute.css\"><link rel=\"stylesheet\" href=\"tablet.css\"></head><body>\r\n<header><a class=\"brand\" href=\"./\"><span class=\"logo\">?</span> 궁금한 교실</a><span class=\"demo\">● API 없는 시연 모드</span><button id=\"reset\" class=\"quiet\">새로 시작하기</button></header>\r\n<main><section class=\"intro\"><div><span class=\"eyebrow\">나의 질문이 배움이 되는 곳</span><h1>오늘은 무엇이<br><em>궁금한가요?</em></h1><p>궁금한 것을 골라도, 직접 물어봐도 좋아요.<br>답을 읽은 뒤에는 다른 자료에서도 확인해 봐요.</p></div><div class=\"illustration\" aria-hidden=\"true\"><span class=\"bubble\">왜 그럴까?</span><div class=\"book\">궁금해!<br><b>●‿●</b></div><span class=\"spark\">✦</span></div></section>\r\n<div class=\"workspace\"><aside><div class=\"section-heading\"><h2>궁금한 것 고르기</h2><span aria-hidden=\"true\">✿</span></div><div id=\"categories\" class=\"categories\"></div><div class=\"tip\"><b>내가 고르는 질문</b><p>정해진 질문이 아니어도 괜찮아요.<br>아래 질문창에 자유롭게 써 보세요.</p></div></aside><section class=\"panel\"><div class=\"panel-head\"><div><span class=\"eyebrow\">질문을 시작해 볼까요?</span><h2 id=\"topic-title\">동물 친구들</h2></div><span id=\"topic-icon\">🐾</span></div><div id=\"animals\" class=\"animals\"></div><section class=\"easy\"><h3>그림으로 쉽게 물어봐요</h3><div id=\"easy-questions\"></div><small>그림을 누르면 질문창에 들어가요. 🔊 버튼으로 들을 수도 있어요.</small></section><div id=\"questions\" class=\"questions\"></div><div class=\"chat-heading\"><h2>나의 대화</h2><span>준비된 예시 답변으로 연습해요</span></div><div id=\"messages\" class=\"messages\" role=\"log\" aria-live=\"polite\"><div class=\"welcome\">안녕하세요! 질문을 골라 보거나 직접 입력해 보세요.<br><small>지금은 실제 AI가 연결되지 않아, 준비한 질문에만 예시 답변을 보여줘요.</small></div></div><form id=\"chat-form\"><label for=\"question\">직접 질문하기</label><div class=\"input-row\"><textarea id=\"question\" rows=\"2\" maxlength=\"1000\" placeholder=\"궁금한 것을 자유롭게 써 보세요.\"></textarea><button class=\"send\" type=\"submit\">질문 보내기 ↗</button></div></form><div class=\"search-bar\"><div><b>답을 읽었다면, 직접 확인해요.</b><span>만든 곳 · 날짜 · 근거를 살펴봐요.</span></div><a href=\"https://www.google.com/\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"search\">⌕ 직접 찾아보기 <small>구글 · 새 탭 ↗</small></a></div><details><summary>자료를 확인했어요 · 내 판단 남기기</summary><p>검색 결과의 짧은 설명만 보지 말고, 원문을 열어 확인해요.</p><fieldset><legend>이 답을 믿어도 될까요?</legend><label><input type=\"radio\" name=\"judgment\" value=\"믿을 만해요\">믿을 만해요</label><label><input type=\"radio\" name=\"judgment\" value=\"내용이 달라요\">내용이 달라요</label><label><input type=\"radio\" name=\"judgment\" value=\"아직 모르겠어요\">아직 모르겠어요</label></fieldset><label for=\"reason\">어떤 자료에서 무엇을 확인했나요?</label><input id=\"reason\" placeholder=\"자료 이름과 확인한 내용을 적거나 선생님께 말해요.\"><button id=\"save-judgment\" class=\"quiet\">판단 남기기</button><p id=\"judgment-status\" role=\"status\"></p></details><section id=\"result\" class=\"result\" hidden><span class=\"eyebrow\">나의 생각을 모았어요</span><h2>🌼 오늘의 배움 기록</h2><p>대화와 내가 남긴 판단을 모은 기록이에요. AI가 만든 요약은 아니에요.</p><div id=\"summary\"></div><button id=\"download-pdf\" class=\"send\">↓ PDF 정리 파일 받기</button><p id=\"pdf-status\" role=\"status\"></p></section></section></div></main><footer>AI도 실수할 수 있어요. 중요한 정보는 다른 자료에서 꼭 확인해요.</footer><script src=\"app.js\"></script><script src=\"report.js\"></script><script src=\"tablet.js\"></script><script src=\"connection.js\"></script></body></html>\r\n","type":"text/html;charset=utf-8"},"/report.js":{"body":"const easyPairs=[{icon:'🐱 🔊 ❓',q:'고양이는 어떻게 울어요?',a:'고양이는 야옹 하고 울어요. 가르릉 같은 다른 소리도 내요.'},{icon:'🐧 🪽 ❓',q:'펭귄은 날아요?',a:'펭귄은 하늘을 날지 못해요. 물속에서는 날개를 움직여 헤엄쳐요.'}];\nconst normalAnswer=answer;answer=q=>{const pair=easyPairs.find(p=>p.q===q);return pair?pair.a+'\\n\\n미리 준비한 시연 답변이에요. 다른 자료에서도 확인해 봐요.':normalAnswer(q)};\nfunction renderEasy(){const root=$('easy-questions');root.replaceChildren();easyPairs.forEach(p=>{const wrap=document.createElement('div');wrap.className='easy-item';const b=document.createElement('button');b.className='easy-card';const icon=document.createElement('span');icon.className='easy-icon';icon.textContent=p.icon;const label=document.createElement('b');label.textContent=p.q;b.append(icon,label);b.onclick=()=>{$('question').value=p.q;$('question').focus()};const read=document.createElement('button');read.className='read';read.textContent='🔊';read.setAttribute('aria-label',p.q+' 소리로 듣기');read.onclick=()=>{if(!('speechSynthesis' in window)){read.textContent='읽기 미지원';return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(p.q);u.lang='ko-KR';u.rate=.8;speechSynthesis.speak(u)};wrap.append(b,read);root.append(wrap)})}\nfunction reportRows(){return records.map((r,i)=>({title:`${i+1}. ${r.question}`,body:[`시연 답변: ${r.answer.replace(/\\n\\n[\\s\\S]*/,'')}`,`내 판단: ${r.judgment||'아직 남기지 않았어요.'}`,`확인 자료와 근거: ${r.reason||'기록하지 않았어요.'}`]}))}\nfunction renderSummary(){const root=$('summary');root.replaceChildren();reportRows().forEach(row=>{const card=document.createElement('article');const h=document.createElement('h3');h.textContent=row.title;card.append(h);row.body.forEach(line=>{const p=document.createElement('p');p.textContent=line;card.append(p)});root.append(card)});$('result').hidden=false}\n$('save-judgment').onclick=()=>{if(latest<0){$('judgment-status').textContent='먼저 질문을 보내고 답변을 읽어 주세요.';return}const selected=document.querySelector('[name=judgment]:checked');if(!selected){$('judgment-status').textContent='먼저 판단을 하나 골라 주세요.';return}records[latest].judgment=selected.value;records[latest].reason=$('reason').value.trim();$('judgment-status').textContent='🌷 이번 질문의 판단을 기록했어요. 아래에서 정리 파일을 받을 수 있어요.';renderSummary()};\n// Browser-local, paginated image PDF: Korean glyphs are drawn by the browser.\nasync function createReportPdf(){await document.fonts.ready;const pages=[];let c,ctx,y;\nfunction page(){c=document.createElement('canvas');c.width=1240;c.height=1754;ctx=c.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#5b467a';ctx.font='bold 34px \"Noto Sans KR\",sans-serif';ctx.fillText('궁금한 교실 · 오늘의 배움 기록',80,100);ctx.fillStyle='#777';ctx.font='20px \"Noto Sans KR\",sans-serif';ctx.fillText('질문과 확인 활동 | '+new Date().toLocaleDateString('ko-KR')+' | '+(pages.length+1)+'쪽',80,145);y=210}\nfunction finish(){ctx.font='18px \"Noto Sans KR\",sans-serif';ctx.fillStyle='#666';ctx.fillText('AI도 실수할 수 있어요. 중요한 정보는 다른 자료에서 꼭 확인해요.',80,1685);pages.push(c.toDataURL('image/jpeg',.94))}\nfunction line(text,bold=false){const size=bold?27:24;ctx.font=`${bold?'bold ':''}${size}px \"Noto Sans KR\",sans-serif`;let buffer='';const flush=()=>{if(y>1590){finish();page();ctx.font=`${bold?'bold ':''}${size}px \"Noto Sans KR\",sans-serif`}ctx.fillStyle=bold?'#57416e':'#30363b';ctx.fillText(buffer,80,y);y+=42;buffer=''};for(const ch of text){if(ch==='\\n'){flush();continue}if(ctx.measureText(buffer+ch).width>1080)flush();buffer+=ch}if(buffer)flush();y+=12}\npage();line('질문하고, 자료를 확인하고, 나의 생각을 남겼어요.');line('이 파일은 대화 내용을 모은 기록입니다. 답변의 종류는 항목별로 표시됩니다. 이 기록은 검증된 정답이나 AI 요약이 아닙니다.');for(const row of reportRows()){line(row.title,true);for(const t of row.body)line(t);y+=22}finish();return jpegPagesPdf(pages)}\nfunction jpegPagesPdf(pages){const encoder=new TextEncoder(),chunks=[],offsets=[0];let length=0;const push=x=>{const bytes=typeof x==='string'?encoder.encode(x):x;chunks.push(bytes);length+=bytes.length};const obj=(id,body)=>{offsets[id]=length;push(`${id} 0 obj\\n`);push(body);push('\\nendobj\\n')};push('%PDF-1.4\\n');obj(1,'<< /Type /Catalog /Pages 2 0 R >>');obj(2,`<< /Type /Pages /Count ${pages.length} /Kids [${pages.map((_,i)=>`${3+i*3} 0 R`).join(' ')}] >>`);pages.forEach((url,i)=>{const n=3+i*3;const raw=atob(url.split(',')[1]);const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));obj(n,`<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595.28 841.89] /Resources << /XObject << /Im0 ${n+1} 0 R >> >> /Contents ${n+2} 0 R >>`);offsets[n+1]=length;push(`${n+1} 0 obj\\n<< /Type /XObject /Subtype /Image /Width 1240 /Height 1754 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${bytes.length} >>\\nstream\\n`);push(bytes);push('\\nendstream\\nendobj\\n');const stream='q\\n595.28 0 0 841.89 0 0 cm\\n/Im0 Do\\nQ\\n';obj(n+2,`<< /Length ${encoder.encode(stream).length} >>\\nstream\\n${stream}endstream`)});const start=length,count=3+pages.length*3;push(`xref\\n0 ${count}\\n0000000000 65535 f \\n`);for(let i=1;i<count;i++)push(String(offsets[i]).padStart(10,'0')+' 00000 n \\n');push(`trailer\\n<< /Size ${count} /Root 1 0 R >>\\nstartxref\\n${start}\\n%%EOF`);return new Blob(chunks,{type:'application/pdf'})}\n$('download-pdf').onclick=async()=>{if(!records.some(r=>r.judgment)){return}const b=$('download-pdf');b.disabled=true;$('pdf-status').textContent='정리 파일을 만들고 있어요…';try{renderSummary();const blob=await createReportPdf();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='궁금한교실_배움기록.pdf';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);$('pdf-status').textContent='PDF 파일을 준비했어요. 다운로드 목록을 확인해 주세요.'}catch(e){$('pdf-status').textContent='파일을 만들지 못했어요. 다시 눌러 주세요.'}finally{b.disabled=false}};renderEasy();\n","type":"text/javascript;charset=utf-8"},"/style.css":{"body":"@import url('https://fonts.googleapis.com/css2?family=Noto+Sans+KR:wght@400;500;600;700;800&family=Jua&display=swap');\n:root{font-family:'Noto Sans KR',sans-serif;color:#263b35;background:#f7f8f2;font-synthesis:none}*{box-sizing:border-box}body{margin:0;padding-bottom:64px}button,a,input,textarea{font:inherit}button,a{touch-action:manipulation}button{cursor:pointer}a{color:inherit;text-decoration:none}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid #df971c;outline-offset:4px}header{height:88px;max-width:1220px;margin:auto;display:flex;align-items:center;gap:22px;padding:0 30px;border-bottom:1px solid #dfe5da}.brand{font-size:22px;font-weight:800;display:flex;align-items:center;gap:12px}.logo{display:grid;place-items:center;width:38px;height:42px;background:#225e49;color:white;border-radius:12px 12px 12px 3px;font-size:28px}.demo{font-size:12px;background:#f6ebd2;color:#765b25;padding:8px 12px;border-radius:20px}.quiet{border:1px solid #ccd7cd;background:white;border-radius:9px;padding:10px 15px;font-size:14px}header .quiet{margin-left:auto}main{max-width:1160px;margin:auto;padding:40px 0}.intro{display:flex;justify-content:space-between;padding:0 24px 38px}.eyebrow{font-size:12px;font-weight:700;letter-spacing:1px;color:#648071}h1{font-size:44px;line-height:1.4;letter-spacing:-2px;margin:14px 0}h1 em{color:#287354;font-style:normal}.intro p{font-size:16px;line-height:1.8;color:#61746a;margin:0}.illustration{position:relative;width:260px;align-self:center;margin-right:75px}.book{background:#dbe9b9;border:2px solid #385e46;box-shadow:8px 7px 0 #f0d66a;border-radius:12px 24px 24px 12px;transform:rotate(8deg);width:150px;height:160px;margin:35px auto 0;text-align:center;padding-top:25px;font-size:22px;font-weight:800}.book b{font-size:40px}.bubble{position:absolute;top:0;left:-20px;background:white;border:1px solid #c6d4c4;border-radius:22px 22px 0 22px;padding:12px 20px;transform:rotate(-8deg)}.spark{position:absolute;right:0;top:20px;color:#b69738;font-size:42px}.workspace{display:grid;grid-template-columns:265px 1fr;gap:28px}aside{padding:22px 16px}.section-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:20px}.section-heading h2{font-size:17px;margin:0}.section-heading span{font-size:12px;color:#7f9484}.categories{display:grid;gap:9px}.category{border:1px solid transparent;background:transparent;padding:16px;text-align:left;border-radius:12px;color:#4a6053;display:flex;align-items:center;gap:13px;font-size:17px}.category:hover{background:#eaf0e3}.category.active{background:#245e48;color:white}.category i{font-style:normal;font-size:23px}.category span:last-child{margin-left:auto;font-size:17px}.tip{margin-top:30px;padding:20px 14px;border-top:1px solid #d9e1d3;font-size:13px;color:#687b6e}.tip p{line-height:1.9}.panel{background:white;border:1px solid #dee5d9;border-radius:24px;padding:30px;box-shadow:0 8px 30px #27412605}.panel-head{display:flex;justify-content:space-between;align-items:center}.panel-head h2{font-size:25px;margin:8px 0 20px;letter-spacing:-1px}#topic-icon{font-size:38px}.animals{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px}.animal{border:1px solid #dce4d7;background:#fff;padding:10px 13px;border-radius:30px;font-size:14px}.animal.active{background:#eaf1df;border-color:#769861;color:#2b583e}.questions{display:grid;grid-template-columns:1fr 1fr;gap:9px}.question-card{padding:16px;background:#f7f8f3;border:1px solid #e5e9dd;border-radius:12px;text-align:left;font-size:15px;color:#3d5244;line-height:1.6;display:flex;gap:10px}.question-card:hover{border-color:#75966d;background:#eff4e7}.question-card span{color:#849b71}.chat-heading{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #e8ecdf;margin-top:28px;padding-top:22px}.chat-heading h2{font-size:17px}.chat-heading span{font-size:11px;color:#7c8175}.messages{max-height:420px;overflow:auto;scroll-behavior:smooth;padding:12px 0 20px;display:flex;flex-direction:column;gap:14px}.welcome{background:#f6f7f3;padding:20px;border-radius:14px;font-size:15px;line-height:1.9;color:#4c6352}.welcome small{display:block;font-size:12px;color:#7b8475;margin-top:8px}.message{max-width:90%;padding:15px 18px;border-radius:16px;line-height:1.8;font-size:15px;white-space:pre-wrap;overflow-wrap:anywhere}.message.user{align-self:flex-end;background:#e8f0db}.message.bot{align-self:flex-start;background:#f3f5f0}.message strong{display:block;font-size:11px;color:#75816b;margin-bottom:5px}form>label{font-size:13px;font-weight:700}.input-row{display:flex;gap:10px;margin-top:9px}textarea{resize:vertical;min-height:78px;width:100%;border:1px solid #cbd8c6;border-radius:12px;padding:15px;font-size:16px}.send{background:#245e48;color:white;border:0;border-radius:12px;width:120px;flex-shrink:0;font-size:14px;font-weight:700}.search-bar{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:20px 0}.search-bar b{font-size:13px}.search-bar span{display:block;font-size:12px;color:#7b8376;margin-top:5px}.search{border:1px solid #d2ddc7;background:#f3f6ed;padding:11px 17px;border-radius:10px;font-weight:700;font-size:14px;white-space:nowrap}.search small{display:block;font-size:10px;color:#77866b;font-weight:400;margin-top:3px}details{border-top:1px solid #e2e8da;padding-top:16px;font-size:14px}summary{cursor:pointer;color:#52684d;font-weight:600}details p{font-size:12px;color:#6b7a62}fieldset{border:0;padding:12px 0;display:flex;flex-wrap:wrap;gap:12px}legend{padding-top:15px}input[type=radio]{accent-color:#245e48}#reason{display:block;width:100%;padding:12px;border:1px solid #d3ddcb;border-radius:8px;margin:10px 0}footer{position:fixed;bottom:0;left:0;right:0;padding:16px;text-align:center;background:#f7f8f2f5;border-top:1px solid #dfe5d8;font-size:13px;color:#52634d;backdrop-filter:blur(10px)}@media(max-width:800px){header{padding:0 18px;height:75px;gap:10px}.brand{font-size:18px}.demo{font-size:10px;padding:6px}header .quiet{font-size:11px;padding:8px}main{padding:25px 16px}.intro{padding:0 8px 25px}h1{font-size:32px}.illustration{display:none}.workspace{grid-template-columns:1fr;gap:12px}aside{padding:0}.section-heading,.tip{display:none}.categories{display:flex;overflow:auto;padding-bottom:10px}.category{white-space:nowrap;padding:12px;font-size:14px}.category span:last-child{display:none}.panel{padding:20px}.chat-heading{align-items:start;gap:8px}.chat-heading span{max-width:130px}.search-bar{flex-wrap:wrap}.questions{grid-template-columns:1fr}.question-card{padding:13px}.send{width:85px}.intro p{font-size:14px}footer{font-size:11px}.message{max-width:96%}}\n","type":"text/css;charset=utf-8"},"/tablet.css":{"body":"html,body{height:100%;overflow:hidden}body{height:var(--app-height,100dvh);padding:0;display:flex;flex-direction:column}header{width:100%;max-width:1200px;min-height:60px;height:60px;flex-shrink:0;padding:8px 24px;flex-wrap:nowrap;border:0}.brand{font-size:21px}.logo{height:34px;width:32px;font-size:25px}main{width:100%;max-width:1200px;margin:0 auto;flex:1;min-height:0;padding:0 20px 8px;display:flex;flex-direction:column;gap:8px}aside{padding:0;flex-shrink:0}.section-heading,.tip{display:none!important}.categories{display:flex;gap:7px;overflow-x:auto;padding:5px 2px 9px;scrollbar-width:thin}.category{flex-shrink:0;white-space:nowrap;min-height:46px;font-size:16px;padding:8px 13px;gap:7px;background:#fff8}.category i{width:28px;height:28px;font-size:22px}.category span:last-child{display:none}.workspace{display:flex;flex:1;min-height:0}.panel{width:100%;display:flex;flex-direction:column;min-height:0;padding:12px 18px;border-radius:24px;box-shadow:0 3px 0 #eee2f0}.chat-tools{display:flex;gap:8px;flex-shrink:0;align-items:center}.chat-tools .quiet,.chat-tools .search{min-height:44px;display:flex;align-items:center;justify-content:center;padding:8px 13px;font-size:14px;white-space:nowrap}.chat-tools .search{margin-left:auto}.chat-heading{margin:8px 0 0;padding:8px 0 0;flex-shrink:0}.chat-heading h2{margin:0;font-size:16px}.chat-heading span{font-size:11px}.messages{flex:1;min-height:0;max-height:none;padding:14px 0;overscroll-behavior:contain}.welcome{margin:auto 0;text-align:center;padding:26px 18px;font-size:17px;background:#faf5fc}.welcome small{max-width:none}.message{font-size:16px}#chat-form{flex-shrink:0;padding-top:8px;border-top:1px solid #eee3f2}#chat-form>label{font-size:12px}.input-row{margin-top:5px;align-items:stretch}.input-row textarea{min-height:52px;max-height:90px;height:52px;resize:none;padding:12px 15px;line-height:24px}.send{min-height:48px}.input-row .send{width:125px}footer{position:static;flex-shrink:0;padding:8px 12px;font-size:12px;line-height:1.5;border:0}.activity-dialog{width:min(720px,calc(100vw - 32px));max-height:calc(var(--app-height,100dvh) - 40px);overflow:auto;border:2px solid #e4d3ed;border-radius:26px;padding:22px;background:#fffcf7;color:#494157;box-shadow:0 20px 80px #47315733;overscroll-behavior:contain}.activity-dialog::backdrop{background:#392a4c55;backdrop-filter:blur(3px)}.dialog-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;position:sticky;top:-22px;background:#fffcf7;z-index:2;padding:10px 0 15px}.dialog-heading h2{font-size:23px;margin:0}.dialog-heading button{min-height:44px}.activity-dialog .panel-head .eyebrow{display:none}.activity-dialog .panel-head h2{font-size:22px;margin:5px 0 15px}.activity-dialog .easy{margin-bottom:15px}.activity-dialog .easy-card{min-height:84px}.activity-dialog .easy-icon{font-size:28px}.activity-dialog .questions{grid-template-columns:1fr 1fr}.activity-dialog details{border:0}.activity-dialog details summary{display:none}.activity-dialog .result{margin-top:14px}.activity-dialog fieldset{gap:8px}.activity-dialog fieldset label{min-height:44px}.activity-dialog #reason{font-size:16px}@media(max-width:600px){header{padding:7px 12px;height:55px;min-height:55px;gap:8px}.brand{font-size:18px}.demo{font-size:9px;padding:5px 7px}header .quiet{font-size:10px;padding:8px;min-height:36px}main{padding:0 8px 5px;gap:3px}.category{font-size:14px;padding:6px 10px}.panel{padding:9px 11px;border-radius:20px}.chat-tools{gap:5px}.chat-tools .quiet,.chat-tools .search{font-size:11px;padding:6px 7px;min-height:42px;flex:1}.chat-heading span{max-width:none}.welcome{font-size:15px;padding:18px 10px}.message{font-size:15px}.input-row .send{width:86px;font-size:12px}.activity-dialog{padding:15px}.dialog-heading{top:-15px}.dialog-heading h2{font-size:19px}.activity-dialog .questions{grid-template-columns:1fr}footer{font-size:10px;padding:6px}.category i{font-size:20px}.logo{display:none}}@media(max-height:500px){header{height:44px;min-height:44px}.category{min-height:38px;padding:3px 10px}.categories{padding:2px}.chat-heading{display:none}footer{padding:3px}.messages{padding:8px 0}.welcome{padding:8px}.welcome small{margin-top:3px}.chat-tools .quiet,.chat-tools .search{min-height:36px}#chat-form>label{display:none}}\n.messages:has(.message) .welcome{display:none}\n.activity-dialog #api-form{display:grid;gap:9px}.activity-dialog #api-form input{font:inherit;padding:12px;border:1px solid #d9c7e5;border-radius:12px;width:100%;box-sizing:border-box}.activity-dialog p{line-height:1.7;font-size:13px}.activity-dialog #api-form .send{width:100%;margin:6px 0 15px}#api-status{white-space:pre-wrap}header .quiet{flex-shrink:0}@media(max-width:600px){header .demo{display:none}header .brand{margin-right:auto}header .quiet{margin-left:0}}\n","type":"text/css;charset=utf-8"},"/tablet.js":{"body":"// Keep the conversation visible; secondary activities open only when requested.\nconst main=document.querySelector('main'),panel=document.querySelector('.panel');\ndocument.querySelector('.intro').remove();\nconst aside=document.querySelector('aside');main.prepend(aside);\nconst toolbar=document.createElement('div');toolbar.className='chat-tools';\nconst choose=document.createElement('button');choose.className='quiet';choose.textContent='💡 예시 질문 고르기';\nconst judge=document.createElement('button');judge.className='quiet';judge.textContent='🌼 내 판단 · PDF';\nconst search=document.querySelector('.search');search.innerHTML='🔎 직접 찾아보기 ↗';toolbar.append(choose,search,judge);panel.prepend(toolbar);\nfunction dialog(title){const d=document.createElement('dialog');d.className='activity-dialog';const head=document.createElement('div');head.className='dialog-heading';const h=document.createElement('h2');h.textContent=title;const close=document.createElement('button');close.className='quiet';close.textContent='닫기 ✕';close.onclick=()=>d.close();head.append(h,close);d.append(head);d.setAttribute('aria-label',title);document.body.append(d);d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}});return d}\nconst picker=dialog('💡 궁금한 질문을 골라요');picker.append(document.querySelector('.panel-head'),$('animals'),document.querySelector('.easy'),$('questions'));\nchoose.onclick=()=>picker.showModal();$('categories').addEventListener('click',e=>{if(e.target.closest('button'))picker.showModal()});\npicker.addEventListener('click',e=>{if(e.target.closest('.question-card,.easy-card')){picker.close();$('question').focus()}});\nconst reflection=dialog('🌼 확인하고 내 생각 남기기');const details=document.querySelector('details');details.open=true;reflection.append(details,$('result'));judge.onclick=()=>reflection.showModal();\ndocument.querySelector('.search-bar').remove();\ndocument.querySelector('.welcome').innerHTML='어떤 것이 궁금한가요? 🌷<br>위에서 주제를 고르거나, 아래에 직접 질문해 보세요.<small>지금은 시연 모드예요. 준비된 질문에 예시 답변을 보여줘요.</small>';\ndocument.querySelector('.chat-heading span').textContent='질문 → 찾아보기 → 내 판단';\n$('question').rows=1;\nconst oldReset=$('reset').onclick;$('reset').onclick=()=>{oldReset();};\nfunction fitViewport(){document.documentElement.style.setProperty('--app-height',(window.visualViewport?.height||window.innerHeight)+'px')}\nwindow.visualViewport?.addEventListener('resize',fitViewport);window.addEventListener('resize',fitViewport);fitViewport();\n","type":"text/javascript;charset=utf-8"}};
const json=(body,status=200,extra={})=>new Response(JSON.stringify(body),{status,headers:{'content-type':'application/json;charset=utf-8','cache-control':'no-store',...extra}});
const name='__Host-classroom-api';
const b64=b=>btoa(String.fromCharCode(...b));const unb64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
async function aes(env){if(!env.API_SESSION_SECRET)throw Error('서버 비밀 설정이 준비되지 않았어요.');return crypto.subtle.importKey('raw',Uint8Array.from(env.API_SESSION_SECRET.match(/.{2}/g),h=>parseInt(h,16)),{name:'AES-GCM'},false,['encrypt','decrypt'])}
async function seal(value,env){const iv=crypto.getRandomValues(new Uint8Array(12));const cipher=await crypto.subtle.encrypt({name:'AES-GCM',iv},await aes(env),new TextEncoder().encode(JSON.stringify(value)));return b64(iv)+'.'+b64(new Uint8Array(cipher))}
async function config(req,env){try{const raw=(req.headers.get('cookie')||'').split(';').map(s=>s.trim()).find(s=>s.startsWith(name+'='))?.slice(name.length+1);if(!raw)return null;const [a,b]=raw.split('.');const bytes=await crypto.subtle.decrypt({name:'AES-GCM',iv:unb64(a)},await aes(env),unb64(b));const c=JSON.parse(new TextDecoder().decode(bytes));return c.until>Date.now()&&c.user===req.headers.get('oai-authenticated-user-id')?c:null}catch{return null}}
const errText=e=>`${e?.name||'Error'}: ${e?.message||e}`+(e?.cause?` (원인: ${e.cause.code||''} ${e.cause.message||e.cause})`:'');
const redact=(s,key)=>key?s.split(key).join('***'):s;
function validUrl(input){const u=new URL(input);if(u.protocol!=='https:'||u.username||u.password||u.search||u.hash||u.port||!u.hostname.includes('.')||!/[a-z]$/i.test(u.hostname)||/localhost|\.local$|\.internal$|\.test$|\.invalid$|\.example$/i.test(u.hostname))throw Error('공개 HTTPS API 주소를 입력해 주세요. 쿼리·비밀번호·포트가 있는 주소는 사용할 수 없어요.');return u.href}
export default {async fetch(req,env){const url=new URL(req.url);if(!url.pathname.startsWith('/api/')){const asset=ASSETS[url.pathname==='/'?'/index.html':url.pathname];return asset?new Response(asset.body,{headers:{'content-type':asset.type,'cache-control':'no-cache'}}):new Response('Not found',{status:404})}
if(!req.headers.get('oai-authenticated-user-id'))return json({error:'로그인이 필요해요.'},401);
if(req.method!=='GET'&&req.headers.get('origin')!==url.origin)return json({error:'허용되지 않은 요청이에요.'},403);
try{if(url.pathname==='/api/config'){if(req.method==='GET'){const c=await config(req,env);return json(c?{connected:true,url:c.url,model:c.model}:{connected:false})}if(req.method==='DELETE')return json({ok:true},200,{'set-cookie':`${name}=; Secure; HttpOnly; SameSite=Strict; Path=/; Max-Age=0`});if(req.method==='POST'){const text=await req.text();if(text.length>5000)return json({error:'설정이 너무 길어요.'},400);const c=JSON.parse(text);const target=validUrl(c.url);if(typeof c.key!=='string'||!c.key.trim()||c.key.length>1000||/[\r\n]/.test(c.key)||typeof c.model!=='string'||!c.model.trim()||c.model.length>120)return json({error:'모델 이름과 올바른 키를 입력해 주세요.'},400);const value=await seal({url:target,key:c.key,model:c.model,user:req.headers.get('oai-authenticated-user-id'),until:Date.now()+8*3600000},env);return json({ok:true},200,{'set-cookie':`${name}=${value}; Secure; HttpOnly; SameSite=Strict; Path=/; Max-Age=28800`})}}
if(url.pathname==='/api/diag'&&req.method==='GET'){const target='https://generativelanguage.googleapis.com/v1beta/models';const started=Date.now();try{const r=await fetch(target,{redirect:'manual',signal:AbortSignal.timeout(10000)});return json({target,reachable:true,status:r.status,ms:Date.now()-started,body:(await r.text()).slice(0,1000),note:'HTTP 상태 코드를 받았다면(키 없이 보내서 400/403이 정상) 서버에서 외부로 나가는 요청은 막혀 있지 않아요.'})}catch(e){return json({target,reachable:false,ms:Date.now()-started,error:errText(e),note:'네트워크 단계에서 실패했어요. 배포 환경이 이 주소로 나가는 요청을 막고 있을 가능성이 높아요.'})}}
if(url.pathname==='/api/chat'&&req.method==='POST'){const c=await config(req,env);if(!c)return json({error:'연결 설정이 없거나 만료되었어요. API 설정을 다시 입력해 주세요.'},401);const raw=await req.text();if(raw.length>20000)return json({error:'대화가 너무 길어요. 새로 시작해 주세요.'},400);const b=JSON.parse(raw);if(!Array.isArray(b.messages)||b.messages.length>13||b.messages.some(m=>!['user','assistant'].includes(m.role)||typeof m.content!=='string'||m.content.length>5000))return json({error:'질문 형식을 확인해 주세요.'},400);let response;try{response=await fetch(c.url,{method:'POST',redirect:'error',headers:{'content-type':'application/json','authorization':'Bearer '+c.key},body:JSON.stringify({model:c.model,max_tokens:400,messages:[{role:'system',content:'초등학생의 학습을 돕는 챗봇입니다. 한국어의 쉬운 말로 2~4문장 답하세요. 모르는 정보는 모른다고 하세요. 학교 급식표, 도서 목록, 학교 행사 자료와 실시간 날씨는 연결되어 있지 않습니다. 이 정보를 추측하지 마세요. 학생 개인정보를 묻지 마세요. 사실과 의견을 구분하고 다른 자료에서 확인하도록 도와주세요.'},...b.messages]}),signal:AbortSignal.timeout(30000)})}catch(e){return json({error:(e.name==='TimeoutError'?'외부 API가 30초 안에 응답하지 않았어요.':'외부 API에 연결하지 못했어요 (네트워크 오류).')+'\n'+errText(e),upstream:{network:true,name:e.name,message:errText(e)}},502)}const text=redact(await response.text().catch(e=>'(본문을 읽지 못함: '+errText(e)+')'),c.key);if(!response.ok)return json({error:`외부 API 오류 · HTTP ${response.status} ${response.statusText}\n${text.slice(0,3000)||'(본문 없음)'}`,upstream:{status:response.status,body:text.slice(0,3000)}},502);let result;try{result=JSON.parse(text)}catch{return json({error:`외부 API 응답이 JSON이 아니에요 · HTTP ${response.status}\n${text.slice(0,3000)}`,upstream:{status:response.status,body:text.slice(0,3000)}},502)}const answer=result.choices?.[0]?.message?.content;if(typeof answer!=='string'||!answer.trim())return json({error:`지원하는 응답 형식이 아니에요. Chat Completions 호환 API인지 확인해 주세요.\n${text.slice(0,3000)}`,upstream:{status:response.status,body:text.slice(0,3000)}},502);return json({answer:answer.slice(0,10000)})}return json({error:'지원하지 않는 요청이에요.'},404)}catch(e){return json({error:e.name==='TimeoutError'?'응답 시간이 길어 연결을 중단했어요. 다시 시도해 주세요.':'요청을 처리하지 못했어요.'+'\n'+errText(e)},400)}}};
